import numpy as np
from scipy.optimize import minimize_scalar
z=np.load('.tmp/circles.npz');w=z['white'];b=z['black']
def fit(V,show=False):
 q=1/(V-170);sc=q-1/(V-b[0,0]);s=lambda x:(q-1/(V-x))/sc
 out=[]
 for st,en,a in [(0,13,w),(17,44,b),(49,95,b)]:
  t=np.arange(en-st)/24;s0=s(a[st:en,0]);p=np.polyfit(t,s0,2);out.append(p)
 dec=np.array([out[0][0],out[1][0],-out[2][0]])*2
 if show:print('V',V,'decel',dec,'params',np.array(out))
 return np.std(dec)
x=minimize_scalar(fit,bounds=(260,300),method='bounded').x;fit(x,True)
for st,en,a in [(0,13,w),(16,44,b)]:print(st,'rpos',np.polyfit(a[st:en,0],a[st:en,2],1))
